-- Fetch bodies for all 11 qualifying tickets
local qualifying_ids = {"T-1002","T-1005","T-1010","T-1013","T-1016","T-1019","T-1020","T-1022","T-1023","T-1026","T-1029"}
local results = {}
for _, id in ipairs(qualifying_ids) do
  local t = tool('get_ticket', { id = id })
  results[#results + 1] = { id = t.id, body = t.body, priority = t.priority, tags = t.tags }
end
return results
